import json, math, urllib.parse, urllib.request, concurrent.futures, os
areas={
'United States':[
('Houston','29.7604','-95.3698','Gulf coastal compound rainfall, river, and surge flooding; critical infrastructure exposure is well documented.','Use as a high-hazard coastal baseline and test how observed-water overlap aligns with infrastructure and watershed planning.','https://prod-01-asg-toolkit-climate.woc.noaa.gov/action-plan/resilient-houston'),
('Miami','25.7617','-80.1918','Coastal rainfall flooding interacts with groundwater table, high tides, and sea-level rise; NOAA-supported research targets prediction and risk management.','Test a shallow-groundwater coastal setting and compare satellite water signals with documented local flood evidence.','https://coastalscience.noaa.gov/news/new-model-enables-rapid-flood-prediction-in-miami-to-support-risk-management/'),
('Tampa','27.9506','-82.4572','USGS documented widespread Milton flooding in its Tampa coverage area, major-stage rivers, and field measurements/gage repairs.','Test an event with independent hydrologic measurements and coastal/river flood context.','https://water.usgs.gov/alerts/item_2024-10-11_20%3A05%3A00.html'),
('New Orleans','29.9511','-90.0715','Low elevation, levees, pumps, and a large catch-basin network create a documented urban rainfall-flood management problem.','Test satellite screening in a pump-dependent, leveed urban drainage environment.','https://marinedebris.noaa.gov/removal/preventing-pervasive-floating-litter-new-orleans-storm-drains'),
('New York City','40.7128','-74.0060','NOAA-hosted research maps present/future flood adaptation areas; infrastructure and power-system exposure are documented.','Test dense coastal infrastructure and compare pluvial/coastal water exposure across an urban asset portfolio.','https://repository.library.noaa.gov/view/noaa/77144'),
('Sacramento','38.5816','-121.4944','The Sacramento region relies on levees along major rivers; USGS maintains streamgages and studies flood processes in California’s Central Valley.','Add an inland river/levee comparator and assess whether water observations can complement gauge-based context.','https://www.usgs.gov/centers/california-water-science-center/science/science-topics/floods'),
('Atlanta','33.7490','-84.3880','The City’s 2025 comprehensive plan calls for stormwater management and flooding mitigation, including capital and watershed actions.','Test an inland urban-runoff case and connect exposure evidence to watershed and public-infrastructure planning.','https://www.atlantaga.gov/home/showpublisheddocument/66053/638884420075030000'),
('St. Louis','38.6270','-90.1994','NOAA/NWS river gauge documentation defines flood stages and describes levee/floodwall impacts along the Mississippi.','Test a major-river and levee comparator with official river-stage context.','https://water.noaa.gov/gauges/eadm7')],
'International':[
('Jakarta','-6.2088','106.8456','Greater Jakarta faces regular widespread flooding alongside water-supply deficits and water-quality challenges; the World Bank calls for integrated urban water management.','Study cross-jurisdictional water exposure and the integration of flood, water-supply, sanitation, and infrastructure planning.','https://www.worldbank.org/en/topic/water/publication/pathways-to-integrated-urban-water-management-for-greater-jakarta'),
('Singapore','1.3521','103.8198','PUB documents flash/coastal flood risks, investments in drainage, a national flood-resilience program, and extensive sensor monitoring.','Test a data-rich, highly urbanized setting where satellite screening can be compared with agency sensors and flood reports.','https://www.pub.gov.sg/Public/KeyInitiatives/Flood-Resilience'),
('Dubai','25.2048','55.2708','Dubai Municipality’s AED 30bn Tasreef program expands stormwater collection and drainage; contracts cover critical urban areas.','Test rapid urban growth and major drainage investment, while treating dry-climate extreme rainfall as an event-based case.','https://www.dm.gov.ae/aed-1-439-billion-contracts-awarded-for-four-tasreef-project-phases/'),
('Mumbai','19.0760','72.8777','India approved an urban flood risk mitigation program that includes Mumbai; city planning and IFLOWS document substantial flood research and warning needs.','Test monsoon, coastal, drainage, and asset exposure; join satellite screening to the city’s flood-warning and mitigation evidence.','https://www.pib.gov.in/PressReleasePage.aspx?PRID=2297625&lang=1&reg=3'),
('Bangkok','13.7563','100.5018','World Bank city-region analysis documents interacting upstream runoff, intense local rainfall, and tidal effects.','Test a deltaic megacity where river, pluvial, and tidal drivers overlap and require cross-system interpretation.','https://documents1.worldbank.org/curated/en/834261468025503285/pdf/508980ESW0v10P1pt1bangkok1report111.pdf'),
('Tokyo','35.6762','139.6503','World Bank work documents Tokyo-region urban flood risk management practice and the need to integrate risk into urban planning and investment.','Test a mature infrastructure context and evaluate water-screening evidence alongside risk-informed planning and engineered controls.','https://www.worldbank.org/en/programs/tokyo-development-learning-center/tdd/tdd_on_urban_flood_management'),
('Manila','14.5995','120.9842','World Bank-supported Metro Manila Flood Management Project targets 17 cities/municipalities and more than one million people with pump/drainage upgrades.','Test a high-need urban drainage and pumping portfolio with documented public investment and operations context.','https://www.worldbank.org/ext/en/topic/water/water-for-planet'),
('São Paulo','-23.5505','-46.6333','World Bank case material documents urban flood exposure, drainage constraints, and the need to combine structural and nonstructural measures.','Test an inland megacity and connect observed-water evidence with drainage, land-use, and asset planning.','https://documents1.worldbank.org/curated/en/659161468182066104/pdf/709820PUB0EPI0067926B09780821389621.pdf')]
}
start='2024-09-01T00:00:00Z'; end='2026-11-02T23:59:59Z'
def q(item):
 region,name,slat,slon,*_=item; lat=float(slat);lon=float(slon); dlat=12.5/111.32;dlon=12.5/(111.32*math.cos(math.radians(lat)))
 bbox=f'{lon-dlon:.6f},{lat-dlat:.6f},{lon+dlon:.6f},{lat+dlat:.6f}'
 params={'short_name':'OPERA_L3_DSWX-S1_V1','temporal':f'{start},{end}','bounding_box':bbox,'page_size':'2000','sort_key[]':'start_date'}
 u='https://cmr.earthdata.nasa.gov/search/granules.json?'+urllib.parse.urlencode(params)
 req=urllib.request.Request(u,headers={'User-Agent':'ATLAS-study-area-screening/1.0'})
 with urllib.request.urlopen(req,timeout=90) as resp:
  data=json.load(resp); hits=int(resp.headers.get('CMR-Hits','0'))
 entries=data.get('feed',{}).get('entry',[]); dates=sorted({e.get('time_start','')[:10] for e in entries if e.get('time_start')})
 return region,name,float(slat),float(slon),bbox,hits,len(dates),dates[0] if dates else '',dates[-1] if dates else '',dates,len(entries)>=hits
items=[(r,*a) for r,ls in areas.items() for a in ls]
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex: metrics=list(ex.map(q,items))
by={(r,n):(lat,lon,bbox,hits,nd,first,last,dates,complete) for r,n,lat,lon,bbox,hits,nd,first,last,dates,complete in metrics}
result=[]
for region,ls in areas.items():
 for name,lat,lon,context,question,url in ls:
  _,_,bbox,hits,nd,first,last,dates,complete=by[(region,name)]
  result.append({'region':region,'city':name,'lat':float(lat),'lon':float(lon),'screening_rationale':context,'value_integration_question':question,'evidence_url':url,'aoi_bbox_wgs84':bbox,'aoi_area_km2':625,'collection':'OPERA_L3_DSWX-S1_V1','temporal_start':start,'temporal_end':end,'cmr_granule_hits':hits,'unique_acquisition_dates':nd,'acquisition_dates':dates,'first_acquisition_date':first,'last_acquisition_date':last,'returned_entries_complete':complete,'status':'candidate; archive metadata screened; QA pixels and independent labels pending'})
obj={'screening_protocol':{'aoi':'25 km × 25 km city-center screening box; approximate WGS84 bounding box, ~625 km²','period':[start,end],'collection':'OPERA_L3_DSWX-S1_V1','screening_gate':'At least 90 distinct acquisition dates for metadata discovery. Passing this gate does not establish valid pixels, flood events, independent reference labels, or inclusion in final analyses.','balanced_design':'For enrolled event studies: same 25 km × 25 km (~625 km²) analysis footprint and prespecified event/baseline rules; require at least 3 QA-valid acquisition dates in each period, each with at least 80% unmasked pixels in the fixed AOI and each asset footprint. When more than 3 dates qualify, select the same number per area using a consistent temporal rule and report all exclusions/missingness. If any area cannot meet the minimum, defer it or reselect before analysis; do not impute. Independent labels must be collected from government/field records not derived from the same satellite product.'},'results':result}
os.makedirs('data',exist_ok=True)
with open('data/study_area_register.json','w') as f: json.dump(obj,f,indent=2)
with open('outputs/atlas-study-area-register.json','w') as f: json.dump(obj,f,indent=2)
